#include <iostream>
using namespace std;

class TokenBucket {
    int capacity, tokens, fillRate;
public:
    TokenBucket(int cap, int rate) : capacity(cap), tokens(cap), fillRate(rate) {}
    bool allowRequest() {
        if (tokens < capacity) tokens++;
        if (tokens > 0) { tokens--; return true; }
        return false;
    }
};

int main() {
    TokenBucket tb(5, 1);
    for (int i = 1; i <= 8; i++)
        cout << "Req " << i << ": " << (tb.allowRequest() ? "Allowed" : "Denied") << endl;
    return 0;
}
